#!/bin/bash
# L20-side launcher: push M6 DGX stage script to DGX, run detached.
# Marker: M6LCH1
MARK=M6LCH1
echo "$MARK L20-BEGIN $(date '+%F %T %Z')"
echo '' | base64 -d > /tmp/m6-dgx-stage.sh
wc -c /tmp/m6-dgx-stage.sh
timeout -k 30 60 scp -i /root/.ssh/dgx_access -o BatchMode=yes -o ConnectTimeout=20 -o StrictHostKeyChecking=accept-new /tmp/m6-dgx-stage.sh arm@10.211.43.155:/tmp/m6-dgx-stage.sh && echo SCP_OK
timeout -k 30 120 ssh -i /root/.ssh/dgx_access -o BatchMode=yes -o ConnectTimeout=20 -o StrictHostKeyChecking=accept-new arm@10.211.43.155 'mkdir -p /home/arm/junyang/carbon/data/dq_logs; nohup bash /tmp/m6-dgx-stage.sh > /home/arm/junyang/carbon/data/dq_logs/m6_stage_outer.log 2>&1 & sleep 6; pgrep -f "m6-dgx-stage[.]sh" | head -3; tail -5 /home/arm/junyang/carbon/data/dq_logs/m6_stage.log 2>/dev/null'
echo "$MARK SSH_RC=$? L20-END"
